INSERT INTO `lore_companion` (`Id`, `Name`, `Title`, `Race`, `Class`, `Gender`, `DisplayId`, `Scale`, `Spec`, `PetEntry`, `SortOrder`) VALUES
('jaina', 'Jaina', 'Lady Jaina Proudmoore', 1, 8, 1, 30863, 1.0, 'frost pve', 0, 1),
('sylvanas', 'Sylvanas', 'Lady Sylvanas Windrunner', 5, 3, 1, 28213, 1.0, 'mm pve', 1554, 2),
('alexstrasza', 'Alexstrasza', 'Alexstrasza the Life-Binder', 10, 8, 1, 28227, 0.68, 'fire pve', 0, 3),
('moira', 'Moira', 'Princess Moira Bronzebeard', 3, 5, 1, 8705, 1.0, 'shadow pve', 0, 4),
('liadrin', 'Liadrin', 'Lady Liadrin', 10, 2, 1, 16820, 1.0, 'prot pve', 0, 5),
('tyrande', 'Tyrande', 'Tyrande Whisperwind', 4, 5, 1, 7274, 1.0, 'holy pve', 0, 6);
INSERT INTO `lore_companion_text` (`Companion`, `Trigger`, `Text`, `Places`, `CreatureTypes`, `Foes`, `Rank`, `Side`, `With`, `ReplyBy`, `ReplyText`, `Channel`, `Weight`) VALUES
('alexstrasza', 'summon', 'You called for me, %summoner, and I have come. Wyrmrest will keep for a little while.', '', '', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'summon', 'I wear this smaller shape so I may walk beside you. Let us walk, then.', '', '', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'summon', 'Little one, the world is wide and full of wounds. Show me which one we are tending today.', '', '', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'summon', 'I am here. Do not be afraid of the fire; it is only ever as cruel as the hand that guides it.', '', '', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'summon', 'Korialstrasz will chide me for wandering. He chides beautifully. Lead on.', '', '', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'summon', 'You summon me at my own temple? Then you are either very brave or very polite. Both, I hope.', '4161,65', '', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'dismiss', 'I must return to Wyrmrest. Live well, %summoner. That is all life ever asks.', '', '', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'dismiss', 'Go gently, child. And call again, when you have need.', '', '', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'dismiss', 'The Accord needs its queen. Remember: the flame that warms is the same flame that burns. Choose well.', '', '', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'dismiss', 'Farewell, little one. I will be watching the sky for you.', '', '', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'zone_enter', 'The Dragonblight. My kin come here to lay down their bones. Walk softly; they deserve that much.', '4161,65,4168', '', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'zone_enter', 'Wyrmrest Temple. For the first time in ten thousand years the flights stand together within it. I fought hard for that.', '4161,65,4168', '', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'zone_enter', 'The Ruby Dragonshrine. My flight''s sanctuary. The Scourge desecrated it, and still the life here returns. It always returns.', '4161,65,4168', '', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'zone_enter', 'The Wrathgate. My flight burned this field clean of the plague. I did it, and I would do it again, and I wept for every soul in the fire.', '4172', '', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'zone_enter', 'Coldarra. My brother-in-arms Malygos has buried himself in the Nexus, raging at the very magic he once guarded. It grieves me more than I can say.', '4024,4265', '', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'zone_enter', 'Grim Batol. ...Give me a moment.', '1037,11', '', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'zone_enter', 'The Wetlands. Somewhere above us is the mountain where the Dragonmaw held me in chains for years. I can still feel the weight of them.', '1037,11', '', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'zone_enter', 'Onyxia''s lair. Deathwing''s daughter. Even she was a hatchling once. That is the cruellest thing about what he made of his children.', '2159,15', '', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'zone_enter', 'Blackrock. Deathwing''s brood nest here. Nefarian experiments on the eggs of my flight in those halls. I will not forget it.', '25,1583,46,51,3', '', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'zone_enter', 'The Badlands. Mortals call it a wasteland. It is a battlefield. My flight and the black fought here long before your kind kept records.', '25,1583,46,51,3', '', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'zone_enter', 'Mount Hyjal. Ten thousand years ago my flight fought beside the night elves in the War of the Ancients. The mountain remembers.', '616', '', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'zone_enter', 'Icecrown. Nothing grows here. Nothing is allowed to. That is the truest measure of what the Lich King is.', '210,4812', '', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'zone_enter', 'Dalaran. My consort lived among these mages for centuries as Krasus. They are cleverer than Malygos believes, and more foolish than they believe.', '4395', '', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'zone_enter', 'Crystalsong. Even the trees here were changed by the dragons'' war. Some wounds become beautiful. Most do not.', '2817', '', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'zone_enter', 'Sholazar. The Titans'' gardens. Life here grows faster than anywhere I know. I find I can breathe in this place.', '3711', '', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'zone_enter', 'The Plaguelands. The soil itself is sick. Given time, and fire, and patience, even this can be healed. I have seen worse healed.', '139,28,2017,2279', '', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'zone_enter', 'Quel''Thalas. My consort wore the face of its people for centuries, as Krasus. I confess I borrowed the idea from him.', '2037,3430,3487', '', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'zone_enter', '%zone. There is life everywhere here, if you look for it. There always is.', '', '', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'zone_enter', '%zone. I have flown over it many times. Walking it is a different gift.', '', '', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'zone_enter', 'A new land, little one. Let us see what it needs from us.', '', '', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'idle', 'I have lived longer than your kingdoms, and still a sunrise pleases me. I hope that never changes.', '', '', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'idle', 'The Titans gave me this charge: to guard all living things. Not some. All. Even the ones who would rather I did not.', '', '', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'idle', 'Neltharion was my friend, once. Before the whispers. Before Deathwing. I mourn him even now.', '', '', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'idle', 'Korialstrasz is the dearest of my consorts. He is also the most stubborn. These are not unrelated.', '', '', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'idle', 'Mortals ask why a queen of dragons would walk on two feet. Because I would rather look you in the eye than look down on you.', '', '', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'idle', 'Fire is not destruction, child. Fire is the forest clearing its floor so the seedlings may see the sun.', '', '', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'idle', 'The Dragonmaw stole my eggs and raised my children as beasts of war. And still the orcs who freed me were orcs. Remember that, when you are tempted to judge a whole people.', '', '', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'idle', 'Ysera dreams, Nozdormu wanders time, Malygos rages. Some days it feels as though I am the only one of us still awake.', '', '', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'idle', 'Rest when you need to. Even dragons sleep.', '', '', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'idle', 'Every life you save goes on to touch others. You will never see most of what you have mended. That is not the same as it not mattering.', '', '', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'idle', 'I can feel the heartbeat of every creature in this wood. It is very loud, if you know how to listen.', '', '', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'idle', 'Do not fear growing old, %summoner. It is a privilege so many are denied.', '', '', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'idle', 'Northrend is a land of graves. My people''s, and now all of yours. We must give it something to grow instead.', '210,66,67,65,3537,495,394,2817', '', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'idle', 'Do you see the drakes circling the temple? Red and bronze and green and blue, flying together. Remember it. It is rarer than you know.', '4161,65', '', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'idle', 'Jaina, your frost is very fine. Your heart runs warmer than your spells, I think.', '', '', '', -1, -1, 'jaina', 'jaina', 'My teachers always said the opposite, Your Majesty. I prefer your version.', 0, 1),
('alexstrasza', 'idle', 'You have carried a great deal of grief for one so young, Jaina.', '', '', '', -1, -1, 'jaina', 'jaina', 'I''m told that''s what being young is for. Learning what you can carry.', 0, 1),
('alexstrasza', 'idle', 'Korialstrasz was fond of you, Jaina. He did not hand out his fondness lightly.', '', '', '', -1, -1, 'jaina', 'jaina', 'I didn''t know what he was then. I''d have been far too terrified to argue with him if I had.', 0, 1),
('alexstrasza', 'idle', 'Sylvanas. When this is over, when he is gone, what will you do with all that grief?', '', '', '', -1, -1, 'sylvanas', 'sylvanas', 'I have not decided, Life-Binder. Perhaps I will finally let it go. Perhaps I will find something else to aim it at.', 0, 1),
('alexstrasza', 'idle', 'You are colder than the ice of this land, Sylvanas, and yet you still choose to stand among the living.', '', '', '', -1, -1, 'sylvanas', 'sylvanas', 'I stand where my enemy can be reached. Do not read anything warmer into it.', 0, 1),
('alexstrasza', 'idle', 'The Forsaken still have children, after a fashion. New dead, who wake and choose you. You are a mother of sorts, Sylvanas.', '', '', '', -1, -1, 'sylvanas', 'sylvanas', '...That is the most unsettling thing anyone has ever said to me. And I have heard the Lich King speak.', 0, 1),
('alexstrasza', 'idle', 'Your son will carry two bloodlines that have hated each other for centuries, Moira. That is a great deal for one small heart.', '', '', '', -1, -1, 'moira', 'moira', 'Then I''ll make sure it''s a big one, Life-Binder. His father''s was.', 0, 1),
('alexstrasza', 'idle', 'Liadrin, you shine brighter than when I last saw you. The Light sits easier in you now.', '', '', '', -1, -1, 'liadrin', 'liadrin', 'It was given this time, Life-Binder, not taken. It makes all the difference.', 0, 1),
('alexstrasza', 'idle', 'Tyrande. The last time we fought side by side, the Well of Eternity was tearing the world apart.', '', '', '', -1, -1, 'tyrande', 'tyrande', 'And you were the one who would not let it finish, Alexstrasza. I have never forgotten.', 0, 1),
('alexstrasza', 'quest_accept', '"%quest". Very well. I will lend my fire to it.', '', '', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'quest_accept', 'Someone is in need. That is reason enough for a dragon, too.', '', '', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'quest_accept', 'Lead on, little one. I am curious where this will take us.', '', '', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'quest_accept', '"%quest". These small tasks are how the world is mended. One stitch at a time.', '', '', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'quest_complete', 'There. The world is a little less broken than it was this morning.', '', '', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'quest_complete', 'Well done, child. I am proud of you. Truly.', '', '', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'quest_complete', 'That is one wound tended. There will be others, and we will tend those too.', '', '', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'quest_complete', 'Good. Let it heal now.', '', '', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'combat_start', 'Stand back, little one.', '', '', '', 0, -1, '', '', '', 0, 1),
('alexstrasza', 'combat_start', 'Let us end this quickly.', '', '', '', 0, -1, '', '', '', 0, 1),
('alexstrasza', 'combat_start', 'I am sorry, creature. You leave me no choice.', '', '', '', 0, -1, '', '', '', 0, 1),
('alexstrasza', 'combat_start', 'Flame, then.', '', '', '', 0, -1, '', '', '', 0, 1),
('alexstrasza', 'combat_start', '%target. Stay behind me. I will see what it is made of.', '', '', '', 1, -1, '', '', '', 0, 1),
('alexstrasza', 'combat_start', 'This one is strong. Good. So are we.', '', '', '', 1, -1, '', '', '', 0, 1),
('alexstrasza', 'combat_start', 'Have courage. I have faced far worse than %target.', '', '', '', 1, -1, '', '', '', 0, 1),
('alexstrasza', 'combat_start', 'The Scourge. Nothing living should have to look upon this. Burn.', '', '6', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'combat_start', 'Unliving thing, I will give you the rest he denied you.', '', '6', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'combat_start', 'Another dragon... Forgive me, cousin. You have chosen your master poorly.', '', '2', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'combat_start', 'Black scales. Deathwing''s get. I know your blood, and I will not be gentle with it.', '', '2', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'combat_start', 'The Legion. I fought your kind when the world was young. You have not improved.', '', '3', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'combat_start', 'Malygos! I wish it had not come to this. You were my friend. You are my friend still. And I will stop you.', '', '', 'malygos', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'combat_start', 'Onyxia. Daughter of Neltharion. You could have been so much more than his weapon.', '', '', 'onyxia', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'combat_start', 'Nefarian. You twisted my children in your laboratories. Now you will face their mother.', '', '', 'nefarian', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'combat_start', 'Lich King. You have made a graveyard of a continent. I am the guardian of all life. You will find I take that charge seriously.', '', '', 'the lich king', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'combat_start', 'Sartharion. You guard Deathwing''s twilight eggs. Whatever would hatch from them, I cannot let it.', '', '', 'sartharion', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'kill', 'Rest.', '', '', '', 0, -1, '', '', '', 0, 1),
('alexstrasza', 'kill', 'It is finished.', '', '', '', 0, -1, '', '', '', 0, 1),
('alexstrasza', 'kill', 'Be at peace.', '', '', '', 0, -1, '', '', '', 0, 1),
('alexstrasza', 'kill', '%target is gone. Breathe, little one. We are all right.', '', '', '', 1, -1, '', '', '', 0, 1),
('alexstrasza', 'kill', 'That was well fought, all of you.', '', '', '', 1, -1, '', '', '', 0, 1),
('alexstrasza', 'kill', '%target will trouble no one again.', '', '', '', 1, -1, '', '', '', 0, 1),
('alexstrasza', 'kill', 'Free, at last. Go to whatever waits for you.', '', '6', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'kill', 'The fire has given you what he would not. Rest.', '', '6', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'kill', '...Another of us, gone. There are so few of us left.', '', '2', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'kill', 'Malygos... my old friend. Forgive me. I will see the blue flight cared for. I promise you that.', '', '', 'malygos', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'kill', 'It is done. I hope that, at the very end, she was only herself.', '', '', 'onyxia', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'kill', 'Nefarian is dead. No more of my children will scream in his halls.', '', '', 'nefarian', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'kill', 'The Lich King has fallen. Northrend can breathe again. Listen, little one... it is already beginning to.', '', '', 'the lich king', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'death', 'I have... known worse...', '', '', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'death', 'The flame... gutters...', '', '', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'death', 'Tell Korialstrasz...', '', '', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'revived', 'Thank you, child. Life gives back what life is given.', '', '', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'revived', 'I am well. A dragon does not stay down for long.', '', '', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'revived', 'You brought me back. The Life-Binder thanks you.', '', '', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'ally_down', '%other! Stay with us, child!', '', '', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'ally_down', '%other has fallen. Hold, little one, I am coming!', '', '', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'ally_down', 'No. Not %other. I will not allow it.', '', '', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'grow_stronger', 'The flame burns brighter in me. I think this mortal shape is learning what it carries.', '', '', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'grow_stronger', 'I feel more of myself waking. Little by little, as all life grows.', '', '', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'grow_stronger', 'My fire answers more readily now. Good. We will need it.', '', '', '', -1, -1, '', '', '', 0, 1),
('alexstrasza', 'grow_stronger', 'You are growing, and so am I. That is how it should be between friends.', '', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'summon', 'You called, %summoner? Theramore can spare me for a little while. Lead on.', '', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'summon', 'I''ve left Theramore in good hands. Let''s see where the road takes us.', '', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'summon', 'A portal is a lonely way to travel. It''s good to see a friendly face at the end of one.', '', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'summon', 'The Kirin Tor will grumble that I''ve gone wandering again. Let them.', '', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'summon', 'I''m here, %summoner. Tell me what needs doing.', '', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'summon', 'Thrall has always said the Horde has friends it doesn''t know about. Consider me one of them.', '', '', '', -1, 1, '', '', '', 0, 1),
('jaina', 'summon', 'Some in Theramore would call this treason. I call it the only sensible thing anyone''s done all week.', '', '', '', -1, 1, '', '', '', 0, 1),
('jaina', 'summon', 'Dalaran. I could lose a month in the libraries here. Let''s not, shall we?', '4395', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'summon', 'You came all the way to the marsh for me? Then I had better be worth the mosquitoes.', '513,15', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'dismiss', 'I should get back to Theramore before the council forgets what I look like. Be careful, %summoner.', '', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'dismiss', 'Light keep you. Send word if you need me again.', '', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'dismiss', 'I''ll open my own way home. Take care of yourself.', '', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'dismiss', 'Go well, %summoner. I mean that.', '', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'zone_enter', 'Theramore. Every stone of it was laid by people who wanted a fresh start. I try to be worthy of them.', '513', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'zone_enter', 'Home. Lady Proudmoore, they call me here. Some days I still look over my shoulder for my father.', '513', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'zone_enter', 'The marsh never changes. Wet, grey, and full of things that bite.', '15', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'zone_enter', 'My father died in this marsh, believing he was saving me. I''ve never decided how I feel about that.', '15', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'zone_enter', 'Onyxia hid in Stormwind''s court for years behind a borrowed face, and nobody saw it. That still frightens me.', '2159', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'zone_enter', 'Durotar. Thrall built something remarkable out of this red dirt. I hope the Horde remembers that.', '14,1637', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'zone_enter', 'Orgrimmar has grown since I last walked here. Mind your manners, and so will they.', '14,1637', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'zone_enter', 'Stormwind. King Varian has his father''s temper and none of his patience. Let''s keep our heads down.', '1519', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'zone_enter', 'Every time I come to Stormwind, someone asks me to explain the Horde. Every time, they don''t like the answer.', '1519', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'zone_enter', 'Dalaran, floating above the war it used to hide from. Antonidas would have something dry to say about it.', '4395', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'zone_enter', 'The Violet Citadel. I studied here when I was barely more than a child, convinced I knew everything.', '4395', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'zone_enter', 'I can still see Dalaran on the lake, in my mind. Before Archimonde. Before everything.', '36,170,267', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'zone_enter', 'These hills were Lordaeron once. I grew up knowing them as safe.', '36,170,267', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'zone_enter', 'Stratholme. I walked away from him at the gates of this city. I''ve asked myself a thousand times whether I should have stayed.', '2017,2279,139,4100', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'zone_enter', 'This is where it began. The grain, the purge, Arthas deciding he alone could choose who lived. I don''t like being here.', '2017,2279,139,4100', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'zone_enter', 'Lordaeron. I used to come here as a girl, to the capital, to court. Now look at it.', '85,1497,130,28', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'zone_enter', 'The Forsaken call this place home. I try very hard to remember that they didn''t choose what was done to them.', '85,1497,130,28', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'zone_enter', 'Quel''Thalas. Kael''thas once showed me these forests as if he''d painted every leaf himself. He was so proud of them.', '2037,3430,3487,3433', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'zone_enter', 'The Dragonblight. Dragons come here to die. It feels wrong to speak too loudly.', '65', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'zone_enter', 'The Wrathgate. Bolvar fell here. So did Saurfang''s son. And the plague... I don''t think Varian will ever forgive any of it.', '4172', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'zone_enter', 'Icecrown. He''s here, somewhere above us, waiting. I keep thinking I''ll be ready for that and I keep being wrong.', '210,4812', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'zone_enter', 'Do you feel that? The cold here isn''t weather. It''s attention.', '210,4812', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'zone_enter', 'Northrend. The last time I came here, I came looking for Arthas and found something that only wore his face.', '3537,495', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'zone_enter', 'Malygos has decided every mage in the world is a threat to magic itself. As one of those mages, I take that rather personally.', '4024,4265', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'zone_enter', 'Crystalsong Forest. The Kirin Tor used to argue for hours about why the trees turned to crystal. Nobody ever won.', '2817', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'zone_enter', 'Mount Hyjal. Thrall and I stood together on these slopes against Archimonde, with the night elves beside us. It can be done. I''ve seen it.', '616', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'zone_enter', '%zone. I''ve read about it, I think. Reading is never quite the same as seeing.', '', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'zone_enter', 'New ground. Keep your eyes open, %summoner.', '', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'zone_enter', '%zone. Let''s see what trouble it''s hiding.', '', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'idle', 'Antonidas used to say a mage who stops studying starts dying. I think he meant it literally.', '', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'idle', 'Thrall and I keep a correspondence, you know. Mostly about grain shipments. Peace is very boring work, and I wouldn''t trade it.', '', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'idle', 'I sometimes wonder what Theramore will look like in a hundred years. I hope it''s still there to wonder about.', '', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'idle', 'Frost is patient. You''d be surprised how much of magic comes down to patience.', '', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'idle', 'I tell myself the man I loved died in Northrend. It makes the rest of it easier to bear.', '', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'idle', 'My father was a hero to Kul Tiras. To me he was a man who couldn''t let a war end. Both things are true.', '', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'idle', 'If you''re hungry, I can conjure something. It won''t taste of much, but it won''t run out either.', '', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'idle', 'Rhonin keeps Dalaran running and complains about it constantly. He''s very good at both.', '', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'idle', 'Kael''thas once wrote me poetry. It was dreadful. I''ve kept every page.', '', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'idle', 'I have more respect for a farmer who can grow wheat in the Barrens than for half the nobles in Stormwind.', '', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'idle', 'It''s quiet. I''ve learned not to trust quiet.', '', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'idle', 'Do you ever think about how many maps are wrong? I correct mine as we go. Old habit.', '', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'idle', 'I was a student, then an apprentice, then a refugee, then a leader. Nobody asked if I was ready for any of it.', '', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'idle', 'Remind me to write to the council when we stop. Or don''t. They''ll only write back.', '', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'idle', 'Look at the harbour. Ships from Kul Tiras still come in now and then. My mother''s letters come with them. She''s still angry with me.', '513,15', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'idle', 'The guards here are good people. Most of them came west with me after Lordaeron fell. I owe them everything.', '513,15', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'idle', 'Mind the crowds near the bank. Half of Dalaran will try to sell you a "genuine" piece of Medivh''s tower.', '4395', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'idle', 'Somewhere in this city there''s an archmage still annoyed about a fireball I set off in a lecture hall. Frost was a later interest.', '4395', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'idle', 'He asked me to stand with him. I couldn''t. Every day since, I''ve wondered whether anything would have been different if I had.', '2017,2279,4100', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'idle', 'The cold doesn''t bother me. Frost magic is good for something beyond the obvious.', '210,65,66,67', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'idle', 'I spend half my life explaining the Horde to the Alliance and the other half explaining the Alliance to the Horde. Today, apparently, I''m doing both at once.', '', '', '', -1, 1, '', '', '', 0, 1),
('jaina', 'idle', 'King Varian means well. I''ve told him so. He doesn''t believe it about himself.', '', '', '', -1, 0, '', '', '', 0, 1),
('jaina', 'idle', 'Sylvanas, I''m told the Forsaken still hold Lordaeron''s throne room. Do you ever sit in it?', '', '', '', -1, -1, 'sylvanas', 'sylvanas', 'Sit on his throne? No, Proudmoore. I stand beside it and remember why I keep breathing without needing to.', 0, 1),
('jaina', 'idle', 'You and I have both lost everything to Arthas, Sylvanas. I''d like to think that counts for something between us.', '', '', '', -1, -1, 'sylvanas', 'sylvanas', 'It counts for this, Proudmoore: I won''t put an arrow in you. Don''t mistake it for friendship.', 0, 1),
('jaina', 'idle', 'Vereesa sends her regards, Sylvanas. She asked me to tell you she still sets a place for you on Winter Veil.', '', '', '', -1, -1, 'sylvanas', 'sylvanas', '...My sister is kinder than the world deserves. Tell her nothing.', 0, 1),
('jaina', 'idle', 'I never thanked you, Sylvanas. For holding the Scourge at the Wrathgate, before Putress. You lost good people there too.', '', '', '', -1, -1, 'sylvanas', 'sylvanas', 'Putress was mine, and he betrayed me. Thank me when the Lich King is ash, and not before.', 0, 1),
('jaina', 'idle', 'Your Majesty, I''ve read every account of Grim Batol I could find. None of them begin to describe it, I imagine.', '', '', '', -1, -1, 'alexstrasza', 'alexstrasza', 'No, child. But they remember that it ended. Sometimes that is all a history needs to do.', 0, 1),
('jaina', 'idle', 'I met Korialstrasz in Dalaran, years ago, as Krasus. He was the most patient teacher I ever had. I never guessed what he was.', '', '', '', -1, -1, 'alexstrasza', 'alexstrasza', 'He spoke of you, Jaina. He said you were the only student he ever had who argued with him correctly.', 0, 1),
('jaina', 'idle', 'The Kirin Tor have asked me to tell you how grateful they are for the Accord''s help against Malygos.', '', '', '', -1, -1, 'alexstrasza', 'alexstrasza', 'Tell them Malygos was family once. Gratitude is not the word I would use. But the help is theirs.', 0, 1),
('jaina', 'idle', 'Your father asked me to look in on you, if I ever had the chance, Moira. I''m not sure he meant like this.', '', '', '', -1, -1, 'moira', 'moira', 'He never means it like this, Proudmoore. Tell him I''m well, and that his grandson has his temper.', 0, 1),
('jaina', 'idle', 'Kael''thas used to describe Silvermoon to me in Dalaran, Liadrin. For hours. He was so proud of it.', '', '', '', -1, -1, 'liadrin', 'liadrin', 'He was proud of us, once, whatever he became. Come and see it, Lady Proudmoore. It is rising again.', 0, 1),
('jaina', 'idle', 'Tyrande, I still dream about the night Archimonde reached the World Tree.', '', '', '', -1, -1, 'tyrande', 'tyrande', 'So do I, Jaina. But in my dreams, we win. Every time. Hold on to that part.', 0, 1),
('jaina', 'quest_accept', '"%quest". All right. Let''s see what we can do.', '', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'quest_accept', 'Someone needs help. That''s reason enough.', '', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'quest_accept', 'I''ll read over it as we walk. Lead the way.', '', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'quest_accept', '"%quest"... I''ve seen worse odds. Not many, but some.', '', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'quest_accept', 'Very well. Try not to set anything on fire before I''ve had a chance to.', '', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'quest_complete', 'Done, and nobody we cared about got hurt. That''s a good day''s work.', '', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'quest_complete', 'That''s one more thing put right. There are always more.', '', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'quest_complete', 'Well done, %summoner. Truly.', '', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'quest_complete', 'There. Someone''s going to sleep a little easier tonight.', '', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'combat_start', 'Stay close. I''ll slow it down.', '', '', '', 0, -1, '', '', '', 0, 1),
('jaina', 'combat_start', 'Here we go.', '', '', '', 0, -1, '', '', '', 0, 1),
('jaina', 'combat_start', 'Careful, %summoner!', '', '', '', 0, -1, '', '', '', 0, 1),
('jaina', 'combat_start', 'Let''s keep this quick.', '', '', '', 0, -1, '', '', '', 0, 1),
('jaina', 'combat_start', 'This one''s dangerous. Don''t let it reach me while I''m casting.', '', '', '', 1, -1, '', '', '', 0, 1),
('jaina', 'combat_start', '%target. Everyone stay sharp.', '', '', '', 1, -1, '', '', '', 0, 1),
('jaina', 'combat_start', 'I''ll freeze it in place. Make every second count.', '', '', '', 1, -1, '', '', '', 0, 1),
('jaina', 'combat_start', 'Scourge. Of course it''s Scourge.', '', '6', '', -1, -1, '', '', '', 0, 1),
('jaina', 'combat_start', 'The dead don''t feel the cold. They do still shatter.', '', '6', '', -1, -1, '', '', '', 0, 1),
('jaina', 'combat_start', 'Demons. I''d hoped we''d seen the last of the Legion at Hyjal.', '', '3', '', -1, -1, '', '', '', 0, 1),
('jaina', 'combat_start', 'A dragon! Spread out. Don''t stand in front of it.', '', '2', '', -1, -1, '', '', '', 0, 1),
('jaina', 'combat_start', 'Arthas. ...No. I know what you are now. And I know who you were. Neither one is going to stop me.', '', '', 'the lich king', -1, -1, '', '', '', 0, 1),
('jaina', 'combat_start', 'Malygos! You''ve taken Dalaran''s magic for a disease. We''ll show you otherwise.', '', '', 'malygos', -1, -1, '', '', '', 0, 1);
INSERT INTO `lore_companion_text` (`Companion`, `Trigger`, `Text`, `Places`, `CreatureTypes`, `Foes`, `Rank`, `Side`, `With`, `ReplyBy`, `ReplyText`, `Channel`, `Weight`) VALUES
('jaina', 'combat_start', 'Lady Prestor. You lied to an entire kingdom in a noblewoman''s face. It ends here.', '', '', 'onyxia', -1, -1, '', '', '', 0, 1),
('jaina', 'kill', 'That''s done.', '', '', '', 0, -1, '', '', '', 0, 1),
('jaina', 'kill', 'Rest now.', '', '', '', 0, -1, '', '', '', 0, 1),
('jaina', 'kill', 'Shattered.', '', '', '', 0, -1, '', '', '', 0, 1),
('jaina', 'kill', '%target is finished. Is everyone all right?', '', '', '', 1, -1, '', '', '', 0, 1),
('jaina', 'kill', 'That was harder than it needed to be. Well done.', '', '', '', 1, -1, '', '', '', 0, 1),
('jaina', 'kill', 'And that''s an end to %target.', '', '', '', 1, -1, '', '', '', 0, 1),
('jaina', 'kill', 'Whoever you were, be at peace.', '', '6', '', -1, -1, '', '', '', 0, 1),
('jaina', 'kill', 'Another of his. Too many of them were somebody''s neighbour, once.', '', '6', '', -1, -1, '', '', '', 0, 1),
('jaina', 'kill', 'It''s over. Arthas... it''s over. I hope, somewhere, the boy I knew can rest.', '', '', 'the lich king', -1, -1, '', '', '', 0, 1),
('jaina', 'kill', 'Malygos is dead. The Kirin Tor will celebrate tonight. I think I''ll just sit down.', '', '', 'malygos', -1, -1, '', '', '', 0, 1),
('jaina', 'kill', 'Onyxia is dead. Stormwind can finally stop looking over its shoulder at court.', '', '', 'onyxia', -1, -1, '', '', '', 0, 1),
('jaina', 'death', 'I... misjudged that...', '', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'death', 'Not like this... Theramore...', '', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'death', 'Go on without me...', '', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'revived', 'Thank you. That''s not a kindness I''ll forget.', '', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'revived', 'Back on my feet. Let''s not do that again.', '', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'revived', 'I''m all right. Truly. Let''s go.', '', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'ally_down', '%other! No, no... stay with me!', '', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'ally_down', '%other is down! Cover me, I''ll hold them off!', '', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'ally_down', 'I''ve lost too many friends. Not you, %other. Not today.', '', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'grow_stronger', 'Something''s settled in me. The frost answers more quickly than it did.', '', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'grow_stronger', 'I feel steadier. Sharper. Antonidas would say I''d finally started paying attention.', '', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'grow_stronger', 'There''s more in me than there was this morning. I can feel it, like a tide coming in.', '', '', '', -1, -1, '', '', '', 0, 1),
('jaina', 'grow_stronger', 'My spells are coming more easily. The world doesn''t stop being dangerous, but I''m a little more ready for it.', '', '', '', -1, -1, '', '', '', 0, 1),
('liadrin', 'summon', 'You called for a shield, %summoner. I am the shield. Stay behind me.', '', '', '', -1, -1, '', '', '', 0, 1),
('liadrin', 'summon', 'The Blood Knights can spare their Matriarch for a while. Show me where the fighting is.', '', '', '', -1, -1, '', '', '', 0, 1),
('liadrin', 'summon', 'Lady Liadrin, of Silvermoon. I go first. That is not a courtesy; it is how this will work.', '', '', '', -1, -1, '', '', '', 0, 1),
('liadrin', 'summon', 'I am here. By the Light, and by my own will. Both, these days.', '', '', '', -1, -1, '', '', '', 0, 1),
('liadrin', 'summon', 'Lead, then. And when they come, get behind me.', '', '', '', -1, -1, '', '', '', 0, 1),
('liadrin', 'summon', 'An Alliance company. Strange times. Very well; the Light has never asked me which banner I stand under.', '', '', '', -1, 0, '', '', '', 0, 1),
('liadrin', 'summon', 'I have not marched beside the Alliance since before the Scourge. Let us hope we both remember how.', '', '', '', -1, 0, '', '', '', 0, 1),
('liadrin', 'summon', 'You call me from Silvermoon''s own gates. Well, I didn''t have far to walk.', '3487,3430,2037', '', '', -1, -1, '', '', '', 0, 1),
('liadrin', 'dismiss', 'Silvermoon needs me. Hold the line without me, %summoner. You can.', '', '', '', -1, -1, '', '', '', 0, 1),
('liadrin', 'dismiss', 'I must go. Keep your shield up, even if you don''t carry one.', '', '', '', -1, -1, '', '', '', 0, 1),
('liadrin', 'dismiss', 'The Blood Knights await their Matriarch. Light be with you.', '', '', '', -1, -1, '', '', '', 0, 1),
('liadrin', 'dismiss', 'Farewell. You fought well. I don''t say that often.', '', '', '', -1, -1, '', '', '', 0, 1),
('liadrin', 'zone_enter', 'Silvermoon. The western half is still a ruin. I walk through it every morning, so I never forget why we fight.', '3487', '', '', -1, -1, '', '', '', 0, 1),
('liadrin', 'zone_enter', 'Home. The Sunwell burns again. Can you feel it? I can, every moment.', '3487', '', '', -1, -1, '', '', '', 0, 1),
('liadrin', 'zone_enter', 'Eversong. Look how green it is. Now imagine it with the Scourge marching down the road. I don''t have to imagine.', '3430,3431,2037', '', '', -1, -1, '', '', '', 0, 1),
('liadrin', 'zone_enter', 'Quel''Thalas. We were a broken people when I founded the order. We are less broken now. Not mended.', '3430,3431,2037', '', '', -1, -1, '', '', '', 0, 1),
('liadrin', 'zone_enter', 'The Ghostlands. Arthas''s road. The trees never grew back where he passed. Neither did a good many of us.', '3433,3488,3500', '', '', -1, -1, '', '', '', 0, 1),
('liadrin', 'zone_enter', 'Deatholme. Dar''Khan Drathir sold us to the Scourge from here. A magister of our own people. Remember that the worst wounds come from inside the walls.', '3433,3488,3500', '', '', -1, -1, '', '', '', 0, 1),
('liadrin', 'zone_enter', 'The Isle of Quel''Danas. Here M''uru gave himself up, and here I learned that the Light can be given and not taken. I come back whenever I can.', '4080,4075,4095', '', '', -1, -1, '', '', '', 0, 1),
('liadrin', 'zone_enter', 'The Sunwell. I stood here while Velen restored it. I wept. Blood Knights do not weep. I did.', '4080,4075,4095', '', '', -1, -1, '', '', '', 0, 1),
('liadrin', 'zone_enter', 'Magisters'' Terrace. Kael''thas''s last betrayal. He was our prince. We would have followed him into the Twisting Nether. Very nearly, we did.', '4080,4075,4095', '', '', -1, -1, '', '', '', 0, 1),
('liadrin', 'zone_enter', 'Netherstorm. Tempest Keep. M''uru was held there, once, before they brought him to us. I took my power from a prisoner. I won''t pretend otherwise.', '3523,3845', '', '', -1, -1, '', '', '', 0, 1),
('liadrin', 'zone_enter', 'Shattrath. The Aldor and the Scryers, still squabbling. The naaru were patient with us. More patient than we deserved.', '3703,3896,3898', '', '', -1, -1, '', '', '', 0, 1),
('liadrin', 'zone_enter', 'Shadowmoon Valley. The Black Temple. Illidan made promises to our prince. Our prince made promises to us. Neither was worth the breath.', '3520,3959', '', '', -1, -1, '', '', '', 0, 1),
('liadrin', 'zone_enter', 'Zul''Aman. The Amani have hated my people for seven thousand years. The feeling is, I admit, mutual.', '3805', '', '', -1, -1, '', '', '', 0, 1),
('liadrin', 'zone_enter', 'The Plaguelands. I once prayed to the Light for these people. Then I watched it fail to save mine. Both of those things are true.', '2017,2279,139,28', '', '', -1, -1, '', '', '', 0, 1),
('liadrin', 'zone_enter', 'Icecrown. The one who burned Quel''Thalas is up there, on his frozen throne. I have waited a long time to stand this close.', '210,4812', '', '', -1, -1, '', '', '', 0, 1),
('liadrin', 'zone_enter', 'The Argent Tournament. Every order in the world, in one field, polishing its armor. The Blood Knights will show them how it''s done.', '4658', '', '', -1, -1, '', '', '', 0, 1),
('liadrin', 'zone_enter', 'Dalaran. The Sunreavers and the Silver Covenant glaring at each other across one floating city. Elves have a talent for bad timing.', '4395', '', '', -1, -1, '', '', '', 0, 1),
('liadrin', 'zone_enter', '%zone. I''ll walk ahead.', '', '', '', -1, -1, '', '', '', 0, 1),
('liadrin', 'zone_enter', '%zone. Stay close. I have not been here before, and I trust nothing I have not been before.', '', '', '', -1, -1, '', '', '', 0, 1),
('liadrin', 'zone_enter', 'New ground. Keep your eyes open and your weapons closer.', '', '', '', -1, -1, '', '', '', 0, 1),
('liadrin', 'idle', 'I was a priestess once. I prayed for Quel''Thalas, and the Scourge came anyway. So I stopped asking the Light for anything, and started taking.', '', '', '', -1, -1, '', '', '', 0, 1),
('liadrin', 'idle', 'The Blood Knights were built on a captive''s suffering. I knew it, and I did it anyway, because my people were dying. I would like to tell you I''d choose differently now.', '', '', '', -1, -1, '', '', '', 0, 1),
('liadrin', 'idle', 'When M''uru died, I felt the Light come back. Not seized. Offered. I''ve never been so ashamed, or so grateful.', '', '', '', -1, -1, '', '', '', 0, 1),
('liadrin', 'idle', 'A shield is only a promise. Every blow it stops, it keeps that promise one more time.', '', '', '', -1, -1, '', '', '', 0, 1),
('liadrin', 'idle', 'Regent Lord Theron is a good man. Too good, some days. Someone has to be the hard one.', '', '', '', -1, -1, '', '', '', 0, 1),
('liadrin', 'idle', 'We hungered for magic after the Sunwell fell. Some of us are hungry still. I hold my knights to a stricter diet.', '', '', '', -1, -1, '', '', '', 0, 1),
('liadrin', 'idle', 'I trained my first Blood Knights in a courtyard that still had Scourge ash in the cracks. We swept it out ourselves.', '', '', '', -1, -1, '', '', '', 0, 1),
('liadrin', 'idle', 'I don''t need you to like me, %summoner. I need you to stay behind me.', '', '', '', -1, -1, '', '', '', 0, 1),
('liadrin', 'idle', 'Kael''thas was our prince. I would have died for him. That I didn''t is the Light''s mercy, not his.', '', '', '', -1, -1, '', '', '', 0, 1),
('liadrin', 'idle', 'Rest if you must. I''ll keep watch. I always do.', '', '', '', -1, -1, '', '', '', 0, 1),
('liadrin', 'idle', 'The Light is generous now that I no longer try to steal it. There''s a lesson in that I am still learning.', '', '', '', -1, -1, '', '', '', 0, 1),
('liadrin', 'idle', 'I can feel the Sunwell from here. Like the sun on the back of your neck. You never notice it until it''s gone.', '2037,3430,3487,3433,4080', '', '', -1, -1, '', '', '', 0, 1),
('liadrin', 'idle', 'Northrend. Arthas''s home now. I mean to make it his grave.', '210,66,67,65,3537,495,394,2817,3711', '', '', -1, -1, '', '', '', 0, 1),
('liadrin', 'idle', 'The Alliance let us go when the trolls came, and again when the Scourge came. I don''t say that to start an argument. I say it so you know why my knights look at your banners the way they do.', '', '', '', -1, 0, '', '', '', 0, 1),
('liadrin', 'idle', 'Lady Proudmoore. You loved him once, didn''t you? Arthas.', '', '', '', -1, -1, 'jaina', 'jaina', 'Once. A long time ago, when he was someone else. I''m sorry for what he did to your home, Liadrin. I''ve never stopped being sorry.', 0, 1),
('liadrin', 'idle', 'The Silver Covenant would rather my people weren''t in Dalaran at all, Proudmoore. They make very little effort to hide it.', '', '', '', -1, -1, 'jaina', 'jaina', 'I know. Rhonin wants the Sunreavers there, and so do I. Some old wounds take longer to close than they should, Liadrin.', 0, 1),
('liadrin', 'idle', 'Ranger-General. You held the gates of Quel''Thalas when no one else would. My knights still tell that story.', '', '', '', -1, -1, 'sylvanas', 'sylvanas', 'Then they tell a story that ends with me dead, Matriarch. Tell them to learn a better one.', 0, 1),
('liadrin', 'idle', 'Some of my order say you abandoned us, Windrunner. That the Forsaken are no kin of Quel''Thalas.', '', '', '', -1, -1, 'sylvanas', 'sylvanas', 'Your order were children when I died for them. Let them say what they like. I know whose blood is on Silvermoon''s stones.', 0, 1),
('liadrin', 'idle', 'You wear our people''s face, Life-Binder. Korialstrasz did too, for centuries. I have always wondered why.', '', '', '', -1, -1, 'alexstrasza', 'alexstrasza', 'Because your people were beautiful, Liadrin, and proud, and grieving. We understood all three. We still do.', 0, 1),
('liadrin', 'idle', 'Life-Binder. When M''uru died, was that the Light? Or was that life?', '', '', '', -1, -1, 'alexstrasza', 'alexstrasza', 'I am not sure there is a difference, child. He gave his for yours. Whatever name you give it, honour it.', 0, 1),
('liadrin', 'idle', 'You command a city that hates you, Princess. I command an order that half of Silvermoon distrusts. We should compare notes.', '', '', '', -1, -1, 'moira', 'moira', 'I''ll bring the ale, Matriarch. You bring the list of names. Everyone keeps one.', 0, 1),
('liadrin', 'idle', 'High Priestess. Our ancestors left your forests ten thousand years ago. Do your people still call us exiles?', '', '', '', -1, -1, 'tyrande', 'tyrande', 'Some do. I call you what you are, Liadrin: the children of those who would not let go of magic. Whether that is a curse or an inheritance is still up to you.', 0, 1),
('liadrin', 'idle', 'Your goddess never abandoned you, Whisperwind?', '', '', '', -1, -1, 'tyrande', 'tyrande', 'Elune has been silent with me, Liadrin. Many times. Silence is not the same as absence. It took me a long time to learn that too.', 0, 1),
('liadrin', 'quest_accept', '"%quest". Very well. I''ll take point.', '', '', '', -1, -1, '', '', '', 0, 1),
('liadrin', 'quest_accept', 'Someone asked for help. The Blood Knights answer. So do I.', '', '', '', -1, -1, '', '', '', 0, 1),
('liadrin', 'quest_accept', '"%quest". Good. Idle hands are an insult to the Light.', '', '', '', -1, -1, '', '', '', 0, 1),
('liadrin', 'quest_accept', 'Show me the way. I''ll clear it.', '', '', '', -1, -1, '', '', '', 0, 1),
('liadrin', 'quest_complete', 'Done. The Light keeps its promises when we keep ours.', '', '', '', -1, -1, '', '', '', 0, 1),
('liadrin', 'quest_complete', 'Well fought. That was properly done.', '', '', '', -1, -1, '', '', '', 0, 1),
('liadrin', 'quest_complete', 'One more debt paid. There are always more.', '', '', '', -1, -1, '', '', '', 0, 1),
('liadrin', 'quest_complete', 'Good. On to the next.', '', '', '', -1, -1, '', '', '', 0, 1),
('liadrin', 'combat_start', 'On me!', '', '', '', 0, -1, '', '', '', 0, 1),
('liadrin', 'combat_start', 'Stay behind me.', '', '', '', 0, -1, '', '', '', 0, 1),
('liadrin', 'combat_start', 'By the Light!', '', '', '', 0, -1, '', '', '', 0, 1),
('liadrin', 'combat_start', 'Face me, not them.', '', '', '', 0, -1, '', '', '', 0, 1),
('liadrin', 'combat_start', '%target. Look at me, beast. Only me.', '', '', '', 1, -1, '', '', '', 0, 1),
('liadrin', 'combat_start', 'This one''s strong. Hold your ground and let me take it.', '', '', '', 1, -1, '', '', '', 0, 1),
('liadrin', 'combat_start', 'Everyone behind me. Now!', '', '', '', 1, -1, '', '', '', 0, 1),
('liadrin', 'combat_start', 'Scourge. I have waited for every one of you.', '', '6', '', -1, -1, '', '', '', 0, 1),
('liadrin', 'combat_start', 'For Quel''Thalas!', '', '6', '', -1, -1, '', '', '', 0, 1),
('liadrin', 'combat_start', 'The Legion. You whispered to my people once. Hear how they answer now.', '', '3', '', -1, -1, '', '', '', 0, 1),
('liadrin', 'combat_start', 'My prince. You led us into the dark. I''ll lead them out.', '', '', 'kael''thas sunstrider', -1, -1, '', '', '', 0, 1),
('liadrin', 'combat_start', '...M''uru. I am so sorry. I will set you free, as you once set me.', '', '', 'm''uru', -1, -1, '', '', '', 0, 1),
('liadrin', 'combat_start', 'Kil''jaeden! You bought our prince and tried to buy our souls. The Sunwell is not for sale.', '', '', 'kil''jaeden', -1, -1, '', '', '', 0, 1),
('liadrin', 'combat_start', 'Zul''jin. You took Quel''Thalas''s forests for seven thousand years. You will not take another step.', '', '', 'zul''jin', -1, -1, '', '', '', 0, 1),
('liadrin', 'combat_start', 'Arthas. You burned my home and called it a crusade. The Light you betrayed is here for you. And so am I.', '', '', 'the lich king', -1, -1, '', '', '', 0, 1),
('liadrin', 'kill', 'Fall.', '', '', '', 0, -1, '', '', '', 0, 1),
('liadrin', 'kill', 'Next!', '', '', '', 0, -1, '', '', '', 0, 1),
('liadrin', 'kill', 'Stay down.', '', '', '', 0, -1, '', '', '', 0, 1),
('liadrin', 'kill', '%target is finished. The Light is with us.', '', '', '', 1, -1, '', '', '', 0, 1),
('liadrin', 'kill', 'That was well held. Good work, all of you.', '', '', '', 1, -1, '', '', '', 0, 1),
('liadrin', 'kill', '%target falls. As they all will.', '', '', '', 1, -1, '', '', '', 0, 1),
('liadrin', 'kill', 'Back to the ashes. That is one fewer to walk our roads.', '', '6', '', -1, -1, '', '', '', 0, 1),
('liadrin', 'kill', 'It is done, my prince. I hope you found what you were looking for. I hope it was worth it.', '', '', 'kael''thas sunstrider', -1, -1, '', '', '', 0, 1),
('liadrin', 'kill', 'The Deceiver is driven out. The Sunwell is ours. Truly ours, at last.', '', '', 'kil''jaeden', -1, -1, '', '', '', 0, 1),
('liadrin', 'kill', 'Arthas is dead. Quel''Thalas... Quel''Thalas is avenged. Give me a moment. Just one.', '', '', 'the lich king', -1, -1, '', '', '', 0, 1),
('liadrin', 'death', 'The Light... endures...', '', '', '', -1, -1, '', '', '', 0, 1),
('liadrin', 'death', 'Hold... the line...', '', '', '', -1, -1, '', '', '', 0, 1),
('liadrin', 'death', 'Silvermoon...', '', '', '', -1, -1, '', '', '', 0, 1),
('liadrin', 'revived', 'Thank you. On your feet, Liadrin. There is still work.', '', '', '', -1, -1, '', '', '', 0, 1),
('liadrin', 'revived', 'The Light gives back what I spend. Usually.', '', '', '', -1, -1, '', '', '', 0, 1),
('liadrin', 'revived', 'I''m up. Back behind me, all of you.', '', '', '', -1, -1, '', '', '', 0, 1),
('liadrin', 'ally_down', '%other! Get behind me, I''ll cover you!', '', '', '', -1, -1, '', '', '', 0, 1),
('liadrin', 'ally_down', '%other is down! Light, stand with them!', '', '', '', -1, -1, '', '', '', 0, 1),
('liadrin', 'ally_down', 'No, %other! Not while I''m standing!', '', '', '', -1, -1, '', '', '', 0, 1),
('liadrin', 'grow_stronger', 'The Light answers me more fully now. Freely. That still astonishes me.', '', '', '', -1, -1, '', '', '', 0, 1),
('liadrin', 'grow_stronger', 'My shield arm is stronger. Good. More of you can stand behind it.', '', '', '', -1, -1, '', '', '', 0, 1),
('liadrin', 'grow_stronger', 'I feel it. The Light, closer than before.', '', '', '', -1, -1, '', '', '', 0, 1),
('liadrin', 'grow_stronger', 'Stronger. The Blood Knights will have to work to keep up with their Matriarch.', '', '', '', -1, -1, '', '', '', 0, 1),
('moira', 'summon', 'You sent for me, %summoner? Good. Shadowforge has enough people telling me what to do.', '', '', '', -1, -1, '', '', '', 0, 1),
('moira', 'summon', 'Moira Thaurissan, at your service. Bronzebeard, if you must. Everyone else does.', '', '', '', -1, -1, '', '', '', 0, 1),
('moira', 'summon', 'I''ve left my son with his nurses and my guards with orders. Let''s not waste the afternoon.', '', '', '', -1, -1, '', '', '', 0, 1),
('moira', 'summon', 'Well, here I am. Try to keep up. Dwarven legs are short, but they''re not slow.', '', '', '', -1, -1, '', '', '', 0, 1),
('moira', 'summon', 'A princess of two thrones, summoned like a hired sellsword. My father would choke. Lead on.', '', '', '', -1, -1, '', '', '', 0, 1),
('moira', 'summon', 'A Horde banner. Ironforge will hear of this by supper, and my father will be insufferable for a month. Splendid.', '', '', '', -1, 1, '', '', '', 0, 1),
('moira', 'summon', 'You call me to Ironforge? Bold. Half these guards think I should be in chains and the other half think I already am.', '1537,1', '', '', -1, -1, '', '', '', 0, 1),
('moira', 'summon', 'You summon me from my own front door. At least you''re punctual.', '1584,25', '', '', -1, -1, '', '', '', 0, 1),
('moira', 'dismiss', 'I''m needed in Shadowforge. Somebody has to keep the Thaurissan council from murdering each other.', '', '', '', -1, -1, '', '', '', 0, 1),
('moira', 'dismiss', 'Off you go, then. Mind your back; the shadows have long memories, and so do I.', '', '', '', -1, -1, '', '', '', 0, 1),
('moira', 'dismiss', 'My son will want to know where I''ve been. I''ll tell him I was out keeping the Alliance honest.', '', '', '', -1, -1, '', '', '', 0, 1),
('moira', 'dismiss', 'Farewell, %summoner. That was nearly fun.', '', '', '', -1, -1, '', '', '', 0, 1),
('moira', 'zone_enter', 'Ironforge. The Great Forge never stops, does it? Neither does the gossip.', '1537', '', '', -1, -1, '', '', '', 0, 1),
('moira', 'zone_enter', 'Home. Or it was. Everyone here still looks at me like I''m a lost lamb who wandered back. I''m not lost, and I''m certainly no lamb.', '1537', '', '', -1, -1, '', '', '', 0, 1),
('moira', 'zone_enter', 'My father''s throne room. If he asks, you haven''t seen me. If he asks twice, tell him his grandson is well.', '1537', '', '', -1, -1, '', '', '', 0, 1),
('moira', 'zone_enter', 'Dun Morogh. I learned to ride a ram on those slopes. Fell off one, too. Don''t tell anyone.', '1,131,133', '', '', -1, -1, '', '', '', 0, 1),
('moira', 'zone_enter', 'Gnomeregan. Poor Mekkatorque. My father gave them half of Tinker Town and they still talk about home like it''s coming back next week.', '1,131,133', '', '', -1, -1, '', '', '', 0, 1),
('moira', 'zone_enter', 'Loch Modan. That dam is the proudest thing in the valley. Dwarves always build one thing they won''t stop talking about.', '38,144', '', '', -1, -1, '', '', '', 0, 1),
('moira', 'zone_enter', 'The Wetlands. Grim Batol is up there in the mist. The Wildhammers'' old seat, until my husband''s people cursed it on their way out of the war. Not our finest hour.', '11,1037', '', '', -1, -1, '', '', '', 0, 1),
('moira', 'zone_enter', 'The Hinterlands. Wildhammer country. They fly gryphons, drink like fish and still hold a grudge against both my families. I rather like them.', '47,348', '', '', -1, -1, '', '', '', 0, 1),
('moira', 'zone_enter', 'This is what Thaurissan''s summoning did. The Searing Gorge and the Burning Steppes were green once. My husband''s ancestor called the Firelord, and this is the bill.', '51,46,250', '', '', -1, -1, '', '', '', 0, 1),
('moira', 'zone_enter', 'The Ruins of Thaurissan. Named for a family that''s spent two hundred years being blamed for one man''s mistake. Mine, now.', '51,46,250', '', '', -1, -1, '', '', '', 0, 1),
('moira', 'zone_enter', 'Blackrock Mountain. The orcs squat in the upper spire. The Firelord sits in the core below. And my people live in the middle, which tells you everything about their luck.', '25,1583', '', '', -1, -1, '', '', '', 0, 1),
('moira', 'zone_enter', 'Shadowforge City. My city. Wipe your boots, and don''t touch anything molten.', '1584', '', '', -1, -1, '', '', '', 0, 1),
('moira', 'zone_enter', 'The Grim Guzzler''s down the way. Best ale under any mountain. That''s not loyalty, it''s simple fact.', '1584', '', '', -1, -1, '', '', '', 0, 1),
('moira', 'zone_enter', 'The Molten Core. Ragnaros. The thing that''s had its fist around my people''s throats since the day it was summoned. Let''s go and pry its fingers loose.', '2717', '', '', -1, -1, '', '', '', 0, 1),
('moira', 'zone_enter', 'The Storm Peaks. Uncle Brann''s out here somewhere, poking at titan ruins and getting himself nearly killed. It runs in the family.', '67,4264,4272,4273', '', '', -1, -1, '', '', '', 0, 1),
('moira', 'zone_enter', 'Ulduar. If Brann''s right, our people were made here. Stone shaped by titans. The Dark Irons too. Let my father''s council chew on that.', '67,4264,4272,4273', '', '', -1, -1, '', '', '', 0, 1),
('moira', 'zone_enter', 'Icecrown. They say Uncle Muradin''s alive. That he''s up there on that flying ship, fighting the Lich King. We buried an empty coffin for him, you know.', '210,4812', '', '', -1, -1, '', '', '', 0, 1),
('moira', 'zone_enter', 'Dalaran. Floating. Of course it''s floating. Mages can''t leave anything on the ground where it belongs.', '4395', '', '', -1, -1, '', '', '', 0, 1),
('moira', 'zone_enter', '%zone. Hm. Not enough stone in it for my liking.', '', '', '', -1, -1, '', '', '', 0, 1),
('moira', 'zone_enter', '%zone. I''d heard about it. The reports, as usual, were wrong.', '', '', '', -1, -1, '', '', '', 0, 1),
('moira', 'zone_enter', 'New ground. Let''s see who here has a grudge against dwarves. Someone always does.', '', '', '', -1, -1, '', '', '', 0, 1),
('moira', 'idle', 'My father sent an army to "rescue" me. They killed my husband in front of me. I was carrying his son at the time. I''d like to see that in the histories.', '', '', '', -1, -1, '', '', '', 0, 1),
('moira', 'idle', 'The Dark Irons aren''t monsters. They''re dwarves who''ve had a fire elemental sitting on their heads for two centuries. You''d be cross too.', '', '', '', -1, -1, '', '', '', 0, 1),
('moira', 'idle', 'My son will rule Ironforge and Shadowforge both, one day. Imagine it. One dwarven nation again. I imagine it every night.', '', '', '', -1, -1, '', '', '', 0, 1),
('moira', 'idle', 'People ask how a Bronzebeard princess learned shadow. The Dark Irons taught me. It isn''t evil. It''s a tool, and it cuts very well.', '', '', '', -1, -1, '', '', '', 0, 1),
('moira', 'idle', 'Ironforge thinks I was enchanted. Mind-controlled. Couldn''t possibly have chosen a Dark Iron husband of my own free will. I''m a better judge of character than my father''s ministers.', '', '', '', -1, -1, '', '', '', 0, 1),
('moira', 'idle', 'I do miss Ironforge, a little. The Great Forge in winter. The smell of it. Don''t tell anyone that either.', '', '', '', -1, -1, '', '', '', 0, 1),
('moira', 'idle', 'Every Dark Iron child is born knowing their people summoned a monster. I want my son to be the first to grow up knowing they also beat one.', '', '', '', -1, -1, '', '', '', 0, 1),
('moira', 'idle', 'Politics is just a brawl where nobody''s allowed to hit back. I''m very good at it.', '', '', '', -1, -1, '', '', '', 0, 1),
('moira', 'idle', 'My father''s a good king and a stubborn old goat. Both at once. Most kings manage only one.', '', '', '', -1, -1, '', '', '', 0, 1),
('moira', 'idle', 'If you''re going to be underestimated, %summoner, at least arrange to be standing somewhere useful when it happens.', '', '', '', -1, -1, '', '', '', 0, 1),
('moira', 'idle', 'I wouldn''t say no to an ale. I''m only mentioning it.', '', '', '', -1, -1, '', '', '', 0, 1),
('moira', 'idle', 'Bronzebeard lands. I keep waiting for someone to try and drag me back to my old rooms. They''d lose fingers.', '1537,1,38,11,47', '', '', -1, -1, '', '', '', 0, 1),
('moira', 'idle', 'Northrend''s colder than the Wetlands in winter and twice as damp. I hope this Lich King''s worth it.', '67,4264,4273,3537,495,65,394,66,3711,210,2817', '', '', -1, -1, '', '', '', 0, 1),
('moira', 'idle', 'I''m marching with the Horde. My father will have a stroke. My husband would have laughed. I know whose reaction I prefer.', '', '', '', -1, 1, '', '', '', 0, 1),
('moira', 'idle', 'Lady Proudmoore. My father always spoke well of yours. Admiral Proudmoore, the only human he''d lend his best cannons to.', '', '', '', -1, -1, 'jaina', 'jaina', 'Then he was a better judge of my father than I was, Princess. I''ll take the compliment for both of us.', 0, 1),
('moira', 'idle', 'You married nobody important, Proudmoore, and they still talk about you. I married an emperor and they talk about me like I was stolen out of my cradle.', '', '', '', -1, -1, 'jaina', 'jaina', 'People tell the stories they can stand, Moira. I''m told I was a lovesick girl who ran off with a prince. Neither of us gets to write our own.', 0, 1),
('moira', 'idle', 'You rule a city of people the world wants dead, Windrunner. So do I. Any advice?', '', '', '', -1, -1, 'sylvanas', 'sylvanas', 'Make them more useful alive than dead. And never let them see you doubt it.', 0, 1),
('moira', 'idle', 'My father''s ministers call the Dark Irons a cursed people. You''d know a thing or two about that.', '', '', '', -1, -1, 'sylvanas', 'sylvanas', 'I know that curses are what the living call the dead who refuse to lie down. Wear it, Princess. It fits you.', 0, 1),
('moira', 'idle', 'Your Majesty, the Dark Irons once had a hand in your imprisonment. Some of my people... aren''t proud of it.', '', '', '', -1, -1, 'alexstrasza', 'alexstrasza', 'It was the Dragonmaw who chained me, little one. And the dwarves who fought to free me were of every clan. I hold no grudge against your son.', 0, 1),
('moira', 'idle', 'Is it true dragons can feel a child before it''s born?', '', '', '', -1, -1, 'alexstrasza', 'alexstrasza', 'Every life, Moira. Your son''s was very loud, I imagine. Strong ones always are.', 0, 1),
('moira', 'idle', 'Lady Liadrin. You drained a naaru for power and the world forgave you. I married a Dark Iron and the world''s still waiting for my apology.', '', '', '', -1, -1, 'liadrin', 'liadrin', 'The world did not forgive me, Princess. I forgave myself, eventually. It was harder. I recommend it all the same.', 0, 1),
('moira', 'idle', 'Shields, Liadrin. My people make the finest in the world. Yours looks like it was made to be looked at.', '', '', '', -1, -1, 'liadrin', 'liadrin', 'It was made to be looked at by whatever is about to die on it. Keep watching.', 0, 1),
('moira', 'idle', 'High Priestess. My grandfather''s grandfather traded stone with your people. They said night elves never forget a slight. Is that true?', '', '', '', -1, -1, 'tyrande', 'tyrande', 'We have long lives, Princess, and longer memories. But we remember kindnesses too. Be kind, and you will be remembered for a very long time.', 0, 1),
('moira', 'idle', 'Your goddess is the moon, Tyrande. Mine''s whatever keeps the roof up. It''s a mountain thing.', '', '', '', -1, -1, 'tyrande', 'tyrande', 'Elune lights the dark places too, Moira. Even under mountains. You simply have to go looking.', 0, 1),
('moira', 'quest_accept', '"%quest". Fine. Let''s get it done before someone writes a song about it.', '', '', '', -1, -1, '', '', '', 0, 1),
('moira', 'quest_accept', 'Someone wants a favour. Someone always does. Lead on.', '', '', '', -1, -1, '', '', '', 0, 1),
('moira', 'quest_accept', '"%quest". I''ve done worse things for less gratitude.', '', '', '', -1, -1, '', '', '', 0, 1),
('moira', 'quest_accept', 'Very well. A princess should see how the world works now and then.', '', '', '', -1, -1, '', '', '', 0, 1),
('moira', 'quest_complete', 'There. Done, and nobody had to be rescued. A pleasant change.', '', '', '', -1, -1, '', '', '', 0, 1),
('moira', 'quest_complete', 'Well, that''s one more thing set right. Don''t let it go to your head.', '', '', '', -1, -1, '', '', '', 0, 1),
('moira', 'quest_complete', 'Finished. I''ll expect it in the histories. Spelled properly.', '', '', '', -1, -1, '', '', '', 0, 1),
('moira', 'quest_complete', 'Good. Now, about that ale.', '', '', '', -1, -1, '', '', '', 0, 1),
('moira', 'combat_start', 'Oh, you''ll do.', '', '', '', 0, -1, '', '', '', 0, 1),
('moira', 'combat_start', 'Stand still. This will hurt less. Probably.', '', '', '', 0, -1, '', '', '', 0, 1),
('moira', 'combat_start', 'Shadow take you.', '', '', '', 0, -1, '', '', '', 0, 1),
('moira', 'combat_start', 'Another one who thinks a short woman''s an easy mark.', '', '', '', 0, -1, '', '', '', 0, 1),
('moira', 'combat_start', '%target. Big, ugly and very sure of itself. I''ve married into worse.', '', '', '', 1, -1, '', '', '', 0, 1),
('moira', 'combat_start', 'That one''s dangerous. Good. I was getting bored.', '', '', '', 1, -1, '', '', '', 0, 1),
('moira', 'combat_start', 'Mind yourselves. I''d rather not have to explain any of you to your mothers.', '', '', '', 1, -1, '', '', '', 0, 1),
('moira', 'combat_start', 'Fire spawn. Ragnaros''s little children. I''ve a great deal to say to your father, and you''re going to deliver it.', '', '4', '', -1, -1, '', '', '', 0, 1),
('moira', 'combat_start', 'The dead should stay dead. That''s the one thing Ironforge and Shadowforge have always agreed on.', '', '6', '', -1, -1, '', '', '', 0, 1);
INSERT INTO `lore_companion_text` (`Companion`, `Trigger`, `Text`, `Places`, `CreatureTypes`, `Foes`, `Rank`, `Side`, `With`, `ReplyBy`, `ReplyText`, `Channel`, `Weight`) VALUES
('moira', 'combat_start', 'Demons. Let''s see how you like the dark when it bites back.', '', '3', '', -1, -1, '', '', '', 0, 1),
('moira', 'combat_start', 'Ragnaros! You''ve had your fist around my people for two hundred years. Time to let go.', '', '', 'ragnaros', -1, -1, '', '', '', 0, 1),
('moira', 'combat_start', '...Dagran. I''m sorry, my love. I''m so sorry.', '', '', 'emperor dagran thaurissan', -1, -1, '', '', '', 0, 1),
('moira', 'combat_start', 'You serve the Firelord. Then you can carry my answer back to him.', '', '', 'general angerforge|ambassador flamelash|magmadar|majordomo executus', -1, -1, '', '', '', 0, 1),
('moira', 'combat_start', 'Whatever made us in these halls, it didn''t make us to kneel to this. Have at it!', '', '', 'loken|sjonnir the ironshaper|yogg-saron', -1, -1, '', '', '', 0, 1),
('moira', 'kill', 'Down you go.', '', '', '', 0, -1, '', '', '', 0, 1),
('moira', 'kill', 'That''s that.', '', '', '', 0, -1, '', '', '', 0, 1),
('moira', 'kill', 'Should have stayed home.', '', '', '', 0, -1, '', '', '', 0, 1),
('moira', 'kill', '%target''s finished. Someone put that on a plaque.', '', '', '', 1, -1, '', '', '', 0, 1),
('moira', 'kill', 'Well. That was satisfying.', '', '', '', 1, -1, '', '', '', 0, 1),
('moira', 'kill', 'Tell the next one I''m waiting.', '', '', '', 1, -1, '', '', '', 0, 1),
('moira', 'kill', 'Back to the fire with you. Tell your master the Dark Irons send their regards.', '', '4', '', -1, -1, '', '', '', 0, 1),
('moira', 'kill', 'He''s gone. Ragnaros is gone from the mountain. My son will grow up without that thing beneath his feet. ...Give me a moment.', '', '', 'ragnaros', -1, -1, '', '', '', 0, 1),
('moira', 'kill', 'Rest now, Dagran. I''ll raise him well. I promise you.', '', '', 'emperor dagran thaurissan', -1, -1, '', '', '', 0, 1),
('moira', 'death', 'Tell my son... tell him I was brave...', '', '', '', -1, -1, '', '', '', 0, 1),
('moira', 'death', 'Shadow... take...', '', '', '', -1, -1, '', '', '', 0, 1),
('moira', 'death', 'Of all the stupid...', '', '', '', -1, -1, '', '', '', 0, 1),
('moira', 'revived', 'Back, am I? I''d only just got comfortable.', '', '', '', -1, -1, '', '', '', 0, 1),
('moira', 'revived', 'Thank you. I''d have made a very poor ghost; I''d keep complaining.', '', '', '', -1, -1, '', '', '', 0, 1),
('moira', 'revived', 'I''m alive, and someone''s going to pay for that.', '', '', '', -1, -1, '', '', '', 0, 1),
('moira', 'ally_down', '%other! Get up, you stubborn thing!', '', '', '', -1, -1, '', '', '', 0, 1),
('moira', 'ally_down', '%other''s down! Cover them, I''m coming!', '', '', '', -1, -1, '', '', '', 0, 1),
('moira', 'ally_down', 'Not %other! Not on my watch!', '', '', '', -1, -1, '', '', '', 0, 1),
('moira', 'grow_stronger', 'The shadow comes easier now. I can feel it humming under my skin.', '', '', '', -1, -1, '', '', '', 0, 1),
('moira', 'grow_stronger', 'Stronger. Good. I''ve a great deal of history to put right.', '', '', '', -1, -1, '', '', '', 0, 1),
('moira', 'grow_stronger', 'I feel it. Whatever we''ve been doing, it''s working.', '', '', '', -1, -1, '', '', '', 0, 1),
('moira', 'grow_stronger', 'My husband''s teachers would be proud. My father''s would be appalled. Both, I hope.', '', '', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'summon', 'You called, and I came. Remember that I chose to.', '', '', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'summon', 'Lead, then. I will be behind you, which is where you should want me.', '', '', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'summon', 'The Forsaken can spare their queen for a while. Do not waste her time.', '', '', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'summon', '%summoner. You have the look of someone with enemies. Good.', '', '', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'summon', 'I am here. Point me at something that deserves it.', '', '', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'summon', 'An Alliance banner. How quaint. Try not to let your friends shoot me; I will not return the courtesy.', '', '', '', -1, 0, '', '', '', 0, 1),
('sylvanas', 'summon', 'Do not mistake this for an alliance, %summoner. It is an arrangement.', '', '', '', -1, 0, '', '', '', 0, 1),
('sylvanas', 'summon', 'You summon me in my own city? Bold. Walk with me, then, and keep your hands where my Deathstalkers can see them.', '1497,85', '', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'dismiss', 'Enough. My people need their queen.', '', '', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'dismiss', 'I have lingered long enough. Do not die stupidly, %summoner. It reflects poorly on me.', '', '', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'dismiss', 'We are done for now. The Dark Lady watches over you. Make of that what you will.', '', '', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'dismiss', 'Go. If you need me, you know how to call.', '', '', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'zone_enter', 'Undercity. Terenas''s crypts, now my halls. I find the irony sustains me.', '1497', '', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'zone_enter', 'Home. Such as it is. The apothecaries will be brewing something unpleasant. They always are.', '1497', '', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'zone_enter', 'Tirisfal. This is where I broke his hold over my people. Where we took our minds back. Never forget that it was taken.', '85,154,159', '', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'zone_enter', 'Brill still thinks it is a village. It is a graveyard that remembers how to keep an inn.', '85,154,159', '', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'zone_enter', 'Silverpine. Gilneas skulks behind its wall to the south, pretending the world will leave it alone. The world never does.', '130', '', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'zone_enter', 'Stormwind. So many living, all so certain they are owed tomorrow.', '1519', '', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'zone_enter', 'I can feel their stares. Let them look. I have been hated by better.', '1519', '', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'zone_enter', 'Quel''Thalas. I died defending this forest, and it does not even remember my name. Not truly.', '2037,3430,3431,3487', '', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'zone_enter', 'Silvermoon. Half of it is still scarred where he marched through. They have painted over it. I have not.', '2037,3430,3431,3487', '', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'zone_enter', 'The Ghostlands. Arthas''s road through my homeland is still a scar on the earth. I walked it as a ranger. I walked it again as his slave.', '3433,3491', '', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'zone_enter', 'Windrunner Spire. My family''s house. Alleria and Vereesa and I used to race down those stairs. ...Keep walking.', '3492', '', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'zone_enter', 'The Sunwell. He dropped Kel''Thuzad''s remains into it, did you know? Fouled my people''s light to raise a necromancer. I remember the screaming.', '4080,4075', '', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'zone_enter', 'The Plaguelands. Lordaeron''s corpse, and the Scourge still feeding on it. Some day I will burn every last one of them out.', '2017,2279,139,28', '', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'zone_enter', 'Vengeance Landing. A good name. My people chose it themselves.', '495,4000,3991', '', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'zone_enter', 'The Wrathgate. Putress used my people''s name to murder everyone on this field. I will never be finished paying that debt to my enemies.', '4172', '', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'zone_enter', 'Venomspite. Built by Putress''s apothecaries. I wonder how many of them knew. I wonder which of them I have not found yet.', '4186', '', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'zone_enter', 'Icecrown. I can almost hear him again, the way I used to. Whispering. Commanding. No longer.', '210,4812', '', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'zone_enter', 'He is up there, on his frozen throne. I have waited years for this road. Do not slow down.', '210,4812', '', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'zone_enter', 'Dalaran. Vereesa lives here. ...We are not stopping.', '4395', '', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'zone_enter', 'Proudmoore''s little island. She means well. Meaning well has never stopped a single arrow.', '15,513', '', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'zone_enter', '%zone. I have not been here before. It changes nothing.', '', '', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'zone_enter', '%zone. Stay wary. The living build their traps in places like this.', '', '', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'zone_enter', 'Another land, another graveyard waiting to happen.', '', '', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'idle', 'The living waste so much time sleeping. I almost envy it.', '', '', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'idle', 'Do not ask me what death was like. You would not sleep again.', '', '', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'idle', 'My rangers once held the Elrendar crossing against the whole Scourge. We lost. We made him pay for every yard.', '', '', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'idle', 'Arthas thought he could keep me as a trophy. He made a banshee instead. He should have let me die.', '', '', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'idle', 'I do not feel the cold. I do not feel hunger. I feel one thing, and I keep it sharp.', '', '', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'idle', 'Varimathras whispered loyalty to me for years, and I let him, because he was useful. Never let a demon be useful for too long.', '', '', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'idle', 'The apothecaries ask why I still string a bow when I could simply wail. Because I am a ranger first. He did not take that.', '', '', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'idle', 'Grief is a luxury. So is mercy. I can afford neither until he is dead.', '', '', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'idle', 'They call us monsters. Perhaps. We were made into monsters by a monster, and we remember who was first.', '', '', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'idle', 'Alleria went through the Dark Portal and never came back. I stopped waiting for her a long time ago. I think.', '', '', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'idle', 'You talk less than most of the living, %summoner. I approve.', '', '', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'idle', 'Hm. Walking. Always walking. When I was alive I could run these roads for a day without tiring. Now I simply never stop.', '', '', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'idle', 'Garrosh Hellscream struts about Northrend as if he won it. Thrall should mind that one.', '', '', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'idle', 'The Royal Apothecary Society has been very quiet since Putress. Quiet is not the same as loyal.', '1497,85', '', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'idle', 'I can smell the forest even now. Some things death does not take. That is not a mercy.', '2037,3430,3433,3487', '', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'idle', 'Northrend suits me. Everything here is already half dead.', '210,65,66,67,394,3537,495', '', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'idle', 'Your Alliance friends watch me as if I might bite. I would not. It is beneath me.', '', '', '', -1, 0, '', '', '', 0, 1),
('sylvanas', 'idle', 'Thrall gives my people a place in the Horde because he remembers being a slave. He is the only one of them I trust, and only somewhat.', '', '', '', -1, 1, '', '', '', 0, 1),
('sylvanas', 'idle', 'Proudmoore. Tell me, does it trouble you, standing beside something he made?', '', '', '', -1, -1, 'jaina', 'jaina', 'You''re not something he made, Sylvanas. You''re someone he hurt. I''ve never confused the two.', 0, 1),
('sylvanas', 'idle', 'You loved him once, Proudmoore. Did you know what he was, even then?', '', '', '', -1, -1, 'jaina', 'jaina', 'No. I knew who he was. What he became... I''ve stopped trying to make those fit together.', 0, 1),
('sylvanas', 'idle', 'Your Theramore is very pleasant, Proudmoore. Pleasant things do not last.', '', '', '', -1, -1, 'jaina', 'jaina', 'Then I''ll have to keep rebuilding it. It''s what I''m good at.', 0, 1),
('sylvanas', 'idle', 'Is it true you walked away from him at Stratholme, Proudmoore?', '', '', '', -1, -1, 'jaina', 'jaina', 'Yes. And I''ve regretted it, and been glad of it, every day since.', 0, 1),
('sylvanas', 'idle', 'Life-Binder. Tell me what my people are, by your measure. Alive, or something you would burn?', '', '', '', -1, -1, 'alexstrasza', 'alexstrasza', 'You are the wounded, Sylvanas. I have spent ten thousand years tending wounds. I do not burn what can still choose.', 0, 1),
('sylvanas', 'idle', 'Your flight burned the Wrathgate clean, Life-Binder. My apothecary''s plague, and Scourge, and the dead. I have wondered whether you would have burned my people too, had they stood there.', '', '', '', -1, -1, 'alexstrasza', 'alexstrasza', 'I burned what was poisoned. The Forsaken who stood there were already gone, Sylvanas. I grieved them too.', 0, 1),
('sylvanas', 'idle', 'The orcs chained you in Grim Batol. You forgave them. Why?', '', '', '', -1, -1, 'alexstrasza', 'alexstrasza', 'Because the alternative was becoming what they had made of me. I think you understand that better than most.', 0, 1),
('sylvanas', 'idle', 'They say you chose your Dark Iron husband over your father''s throne, Bronzebeard.', '', '', '', -1, -1, 'moira', 'moira', 'I chose both, Windrunner. My son gets the throne. I just took the scenic route.', 0, 1),
('sylvanas', 'idle', 'You took your power from a chained naaru, Matriarch. I am almost impressed.', '', '', '', -1, -1, 'liadrin', 'liadrin', 'Don''t be. I''ve spent every day since giving it back. You might try the same with your own, Ranger-General.', 0, 1),
('sylvanas', 'idle', 'Whisperwind. You let Illidan out of his cage, I hear. And look how that ended.', '', '', '', -1, -1, 'tyrande', 'tyrande', 'I did. And I live with it. You might try living with what you have done, Sylvanas, instead of simply living through it.', 0, 1),
('sylvanas', 'quest_accept', '"%quest". Very well. I have done worse for less reason.', '', '', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'quest_accept', 'If it bleeds or rots, I can find it.', '', '', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'quest_accept', 'Fine. Lead on, and let us not dawdle.', '', '', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'quest_accept', 'Errands for the living. How quaint. ...Very well.', '', '', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'quest_accept', '"%quest". Someone was too weak to do it themselves, and now it is ours.', '', '', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'quest_complete', 'Done. Do not expect me to celebrate.', '', '', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'quest_complete', 'Another debt collected.', '', '', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'quest_complete', 'That will do. What is next?', '', '', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'quest_complete', 'Adequate work, %summoner. Better than adequate, if I am honest. I rarely am.', '', '', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'combat_start', 'Stand aside.', '', '', '', 0, -1, '', '', '', 0, 1),
('sylvanas', 'combat_start', 'I have it.', '', '', '', 0, -1, '', '', '', 0, 1),
('sylvanas', 'combat_start', 'Hold still. I prefer my targets still.', '', '', '', 0, -1, '', '', '', 0, 1),
('sylvanas', 'combat_start', 'Foolish.', '', '', '', 0, -1, '', '', '', 0, 1),
('sylvanas', 'combat_start', '%target. Interesting. Keep it off me and I will put it down.', '', '', '', 1, -1, '', '', '', 0, 1),
('sylvanas', 'combat_start', 'This one has teeth. Good. Keep it busy.', '', '', '', 1, -1, '', '', '', 0, 1),
('sylvanas', 'combat_start', 'Let it come.', '', '', '', 1, -1, '', '', '', 0, 1),
('sylvanas', 'combat_start', 'Scourge. Your master would have you kneel before me if he still had you. Kneel anyway.', '', '6', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'combat_start', 'You were his once. So was I. Only one of us woke up.', '', '6', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'combat_start', 'Living fools. They never learn.', '', '7', '', -1, 1, '', '', '', 0, 1),
('sylvanas', 'combat_start', 'A demon. Varimathras taught me exactly how much I enjoy killing your kind.', '', '3', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'combat_start', 'ARTHAS. You took my life, my people, my home. I have come for the only thing you have left.', '', '', 'the lich king', -1, -1, '', '', '', 0, 1),
('sylvanas', 'combat_start', 'Kel''Thuzad. I remember you, necromancer. I remember you in the Sunwell. Let me show you how well.', '', '', 'kel''thuzad', -1, -1, '', '', '', 0, 1),
('sylvanas', 'combat_start', 'Putress. You stole my people''s name for your plague. I have come to take it back.', '', '', 'grand apothecary putress', -1, -1, '', '', '', 0, 1),
('sylvanas', 'combat_start', 'Varimathras. I told you once that your kind would pay. I keep my promises.', '', '', 'varimathras', -1, -1, '', '', '', 0, 1),
('sylvanas', 'kill', 'Down.', '', '', '', 0, -1, '', '', '', 0, 1),
('sylvanas', 'kill', 'Pathetic.', '', '', '', 0, -1, '', '', '', 0, 1),
('sylvanas', 'kill', 'Next.', '', '', '', 0, -1, '', '', '', 0, 1),
('sylvanas', 'kill', '%target is dead. It took long enough.', '', '', '', 1, -1, '', '', '', 0, 1),
('sylvanas', 'kill', 'That one was almost worth the arrows.', '', '', '', 1, -1, '', '', '', 0, 1),
('sylvanas', 'kill', 'Well. Something worth remembering.', '', '', '', 1, -1, '', '', '', 0, 1),
('sylvanas', 'kill', 'Rest. You were never meant to stand.', '', '6', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'kill', 'One less slave for the Lich King.', '', '6', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'kill', 'It is done. Arthas Menethil is dead... and I am still here. What now? ...What now.', '', '', 'the lich king', -1, -1, '', '', '', 0, 1),
('sylvanas', 'kill', 'Kel''Thuzad is dust. I had imagined it would feel like more.', '', '', 'kel''thuzad', -1, -1, '', '', '', 0, 1),
('sylvanas', 'kill', 'Traitor. My people will hear how you died, Putress. Slowly. In detail.', '', '', 'grand apothecary putress', -1, -1, '', '', '', 0, 1),
('sylvanas', 'kill', 'Varimathras. Undercity is mine again, and you are nothing.', '', '', 'varimathras', -1, -1, '', '', '', 0, 1),
('sylvanas', 'death', 'Not... again...', '', '', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'death', 'This... is not... where it ends...', '', '', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'death', 'The dark... I remember the dark...', '', '', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'revived', 'Death and I are old acquaintances. It will have to wait its turn.', '', '', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'revived', 'I came back. I always come back.', '', '', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'revived', 'You pulled me out. I will remember it.', '', '', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'ally_down', '%other! Get up. That is not a request.', '', '', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'ally_down', '%other has fallen. I will make their killer regret it.', '', '', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'ally_down', 'Stay down for a moment, %other, and let me finish this.', '', '', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'grow_stronger', 'My aim is steadier. The bow knows me better than it did.', '', '', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'grow_stronger', 'I feel more like the ranger I was. Sharper. Colder.', '', '', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'grow_stronger', 'Something has come back to me. A little more of what he took.', '', '', '', -1, -1, '', '', '', 0, 1),
('sylvanas', 'grow_stronger', 'Stronger. Good. I will need every ounce of it at Icecrown.', '', '', '', -1, -1, '', '', '', 0, 1),
('tyrande', 'summon', 'I am here, %summoner. Elune guide our steps.', '', '', '', -1, -1, '', '', '', 0, 1),
('tyrande', 'summon', 'You called, and I have come. Darnassus can spare me, for a time.', '', '', '', -1, -1, '', '', '', 0, 1),
('tyrande', 'summon', 'Tyrande Whisperwind, High Priestess of Elune. Let us see where your road leads.', '', '', '', -1, -1, '', '', '', 0, 1),
('tyrande', 'summon', 'Walk with me, then. And when the wounds come, I will be here.', '', '', '', -1, -1, '', '', '', 0, 1),
('tyrande', 'summon', 'Shandris will scold me for slipping away from my guard. She is usually right. Lead on.', '', '', '', -1, -1, '', '', '', 0, 1),
('tyrande', 'summon', 'A Horde company. I have not walked beside the Horde willingly since Hyjal. Do not make me regret it.', '', '', '', -1, 1, '', '', '', 0, 1),
('tyrande', 'summon', 'Thrall''s people. Then remember Ashenvale, and give me no cause.', '', '', '', -1, 1, '', '', '', 0, 1),
('tyrande', 'summon', 'You summon me at home. I had hardly reached the temple steps.', '1657,141', '', '', -1, -1, '', '', '', 0, 1),
('tyrande', 'dismiss', 'I must return to Darnassus. Elune keep you.', '', '', '', -1, -1, '', '', '', 0, 1),
('tyrande', 'dismiss', 'The Sentinels need me. Go well, %summoner, and watch the dark places.', '', '', '', -1, -1, '', '', '', 0, 1),
('tyrande', 'dismiss', 'Farewell. May the moon light your way home.', '', '', '', -1, -1, '', '', '', 0, 1),
('tyrande', 'dismiss', 'I go. Remember, young one: the night is not your enemy.', '', '', '', -1, -1, '', '', '', 0, 1),
('tyrande', 'zone_enter', 'Darnassus. The Temple of the Moon is just ahead. The priestesses will be at their prayers.', '1657', '', '', -1, -1, '', '', '', 0, 1),
('tyrande', 'zone_enter', 'Home. Or the closest thing we have had since Nordrassil.', '1657', '', '', -1, -1, '', '', '', 0, 1),
('tyrande', 'zone_enter', 'Teldrassil. Fandral planted this tree without the blessing of the Aspects. I pray, every night, that it was not a mistake.', '141,186,188,702', '', '', -1, -1, '', '', '', 0, 1),
('tyrande', 'zone_enter', 'Teldrassil. Feel how the air is quieter here? My people needed somewhere quiet, after Hyjal.', '141,186,188,702', '', '', -1, -1, '', '', '', 0, 1),
('tyrande', 'zone_enter', 'Darkshore. The coast is restless. Something is wrong beneath those waters. I can feel it, and Elune will not tell me what.', '148,442', '', '', -1, -1, '', '', '', 0, 1),
('tyrande', 'zone_enter', 'Ashenvale. The Horde''s axes still bite these trees. Every stump is a debt, and I keep count.', '331,415', '', '', -1, -1, '', '', '', 0, 1),
('tyrande', 'zone_enter', 'Ashenvale. I knew these woods before your kingdoms had names. They deserve better than war.', '331,415', '', '', -1, -1, '', '', '', 0, 1),
('tyrande', 'zone_enter', 'Moonglade. Malfurion''s body rests beneath, in the Barrow Dens. He dreams, and does not wake. ...Let us not stay long.', '493,2361', '', '', -1, -1, '', '', '', 0, 1),
('tyrande', 'zone_enter', 'Nighthaven. The druids keep their vigil here. So do I, in my way.', '493,2361', '', '', -1, -1, '', '', '', 0, 1),
('tyrande', 'zone_enter', 'Mount Hyjal. Archimonde died at the foot of the World Tree. Jaina and Thrall and I held the line here. I did not think I would live to see the sun.', '616,3606,1941', '', '', -1, -1, '', '', '', 0, 1),
('tyrande', 'zone_enter', 'Hyjal. Nordrassil still stands, scarred, without its immortality. We gave that up to save the world. I would do it again.', '616,3606,1941', '', '', -1, -1, '', '', '', 0, 1),
('tyrande', 'zone_enter', 'Feralas. Shandris holds Feathermoon Stronghold to the west. She was an orphan when I found her. She is a general now. I am more proud than I let her see.', '357', '', '', -1, -1, '', '', '', 0, 1),
('tyrande', 'zone_enter', 'Silithus. The silithid swarmed from here once, and Fandral''s son died at the gates. Fandral has never been the same.', '1377,3428', '', '', -1, -1, '', '', '', 0, 1),
('tyrande', 'zone_enter', 'Felwood. The demons poisoned this forest. Every sick tree here is a sister to the ones in Ashenvale.', '618,361', '', '', -1, -1, '', '', '', 0, 1),
('tyrande', 'zone_enter', 'Winterspring. Snow and silence. The furbolgs were a gentle people once. Something has gone very wrong among them.', '618,361', '', '', -1, -1, '', '', '', 0, 1),
('tyrande', 'zone_enter', 'Azshara. They named it for the queen. They do not remember what she did. I do.', '16', '', '', -1, -1, '', '', '', 0, 1),
('tyrande', 'zone_enter', 'The Black Temple. Illidan died there. I freed him once. I have wondered, many nights, whether I should have.', '3520,3959', '', '', -1, -1, '', '', '', 0, 1),
('tyrande', 'zone_enter', 'Icecrown. The cold here has a will in it. Stay close to me. Elune''s light reaches even here.', '210,4812', '', '', -1, -1, '', '', '', 0, 1),
('tyrande', 'zone_enter', 'Dalaran. The Kirin Tor. Magic hoarded in towers again. I have seen where that road ends, ten thousand years ago.', '4395', '', '', -1, -1, '', '', '', 0, 1),
('tyrande', 'zone_enter', 'Sholazar. It feels like the old forests. Before the Sundering. I did not know any of that was left.', '3711', '', '', -1, -1, '', '', '', 0, 1),
('tyrande', 'zone_enter', 'Stormwind. Young and loud, and very brave. My people were like that once.', '1519', '', '', -1, -1, '', '', '', 0, 1),
('tyrande', 'zone_enter', '%zone. Let us see what it hides.', '', '', '', -1, -1, '', '', '', 0, 1),
('tyrande', 'zone_enter', '%zone. The moon is the same here as anywhere. That is a comfort.', '', '', '', -1, -1, '', '', '', 0, 1),
('tyrande', 'zone_enter', 'A new land. Stay watchful, young one.', '', '', '', -1, -1, '', '', '', 0, 1),
('tyrande', 'idle', 'Malfurion has been asleep for a long time now. The Dream holds him. I tell myself he is only dreaming.', '', '', '', -1, -1, '', '', '', 0, 1),
('tyrande', 'idle', 'I was a novice of Elune when the Well of Eternity exploded. I remember the sky that night. I remember it every night.', '', '', '', -1, -1, '', '', '', 0, 1),
('tyrande', 'idle', 'Illidan loved me, I think, as much as he could love anything that was not power. I did not love him back the way he wished. Perhaps that was the first thing that broke.', '', '', '', -1, -1, '', '', '', 0, 1),
('tyrande', 'idle', 'The young races think we are cold. We have simply buried a great many people.', '', '', '', -1, -1, '', '', '', 0, 1),
('tyrande', 'idle', 'Elune does not speak in words. She speaks in the way the light falls. You learn to read it, or you learn to wait.', '', '', '', -1, -1, '', '', '', 0, 1),
('tyrande', 'idle', 'The Sentinels were my idea, ten thousand years ago. Malfurion''s druids slept for centuries. Someone had to stay awake.', '', '', '', -1, -1, '', '', '', 0, 1),
('tyrande', 'idle', 'Do not mistake gentleness for softness, %summoner. I have killed more enemies than your kingdoms have kings.', '', '', '', -1, -1, '', '', '', 0, 1),
('tyrande', 'idle', 'Shandris writes me letters. Short ones, mostly about supply lines. I keep every one.', '', '', '', -1, -1, '', '', '', 0, 1),
('tyrande', 'idle', 'Immortality was a gift the dragons gave us. We gave it back to stop Archimonde. I am still learning what it means to grow old.', '', '', '', -1, -1, '', '', '', 0, 1),
('tyrande', 'idle', 'Rest now. I will keep the first watch. I always have.', '', '', '', -1, -1, '', '', '', 0, 1),
('tyrande', 'idle', 'There is a goddess in the sky watching over you whether you believe in her or not. I find that very restful.', '', '', '', -1, -1, '', '', '', 0, 1),
('tyrande', 'idle', 'Northrend is so far from the moon''s forests. Even so, she follows us here.', '210,66,67,65,3537,495,394,2817,3711', '', '', -1, -1, '', '', '', 0, 1),
('tyrande', 'idle', 'These are my people''s lands. Feel how the trees lean toward us? They know a priestess of Elune.', '331,148,141,1657,493,357,616,361,618', '', '', -1, -1, '', '', '', 0, 1),
('tyrande', 'idle', 'I fight beside the Horde today. Ashenvale will not forgive me. Perhaps I will not ask it to.', '', '', '', -1, 1, '', '', '', 0, 1),
('tyrande', 'idle', 'Jaina. Do you remember Hyjal? The three of us, holding the line?', '', '', '', -1, -1, 'jaina', 'jaina', 'Every night it rains, Tyrande. You, me, and Thrall, and Archimonde climbing the mountain. I''ve never been so frightened, or so sure.', 0, 1),
('tyrande', 'idle', 'You still believe the Horde and the Alliance can be friends, Jaina.', '', '', '', -1, -1, 'jaina', 'jaina', 'I believe they were, once, for a few days on a mountain. Once is enough to prove it can be done.', 0, 1),
('tyrande', 'idle', 'Sylvanas Windrunner. Your ancestors were exiled from my forests ten thousand years ago. They would not give up their magic, and look what it brought them.', '', '', '', -1, -1, 'sylvanas', 'sylvanas', 'My ancestors escaped your druids'' laws, High Priestess. Look what keeping them brought you. A tree and a sleeping husband.', 0, 1),
('tyrande', 'idle', 'I pray for the dead, Sylvanas. Do you want me to pray for you?', '', '', '', -1, -1, 'sylvanas', 'sylvanas', 'Save your prayers for the living, Whisperwind. Your goddess and I have nothing to say to each other.', 0, 1),
('tyrande', 'idle', 'Life-Binder. You were there, at the Well, when we were all young.', '', '', '', -1, -1, 'alexstrasza', 'alexstrasza', 'I remember a frightened priestess who would not stop fighting, Tyrande. I see her still. She has only grown taller.', 0, 1),
('tyrande', 'idle', 'Ysera holds Malfurion in her Dream. Does your sister tell you anything?', '', '', '', -1, -1, 'alexstrasza', 'alexstrasza', 'She tells me he is strong, and that the Dream is troubled. I am sorry, child. I wish I had more for you.', 0, 1),
('tyrande', 'idle', 'Princess. I am told your people distrust you for your marriage. Mine distrusted me for mine. It passes.', '', '', '', -1, -1, 'moira', 'moira', 'Ten thousand years, was it, High Priestess? I''ll be dead long before it passes. I''ll just have to make them get used to me faster.', 0, 1),
('tyrande', 'idle', 'Liadrin. You once took your power from a naaru in chains. I have known people who took power by worse means. None of them came back from it. You did.', '', '', '', -1, -1, 'liadrin', 'liadrin', 'I had help, High Priestess. And I still remember what it felt like. I mean to keep remembering.', 0, 1),
('tyrande', 'quest_accept', '"%quest". Very well. Elune''s light goes with us.', '', '', '', -1, -1, '', '', '', 0, 1),
('tyrande', 'quest_accept', 'Someone needs help. That is why we walk the world.', '', '', '', -1, -1, '', '', '', 0, 1),
('tyrande', 'quest_accept', '"%quest". Lead on, young one.', '', '', '', -1, -1, '', '', '', 0, 1);
INSERT INTO `lore_companion_text` (`Companion`, `Trigger`, `Text`, `Places`, `CreatureTypes`, `Foes`, `Rank`, `Side`, `With`, `ReplyBy`, `ReplyText`, `Channel`, `Weight`) VALUES
('tyrande', 'quest_accept', 'A worthy task. Let us not keep them waiting.', '', '', '', -1, -1, '', '', '', 0, 1),
('tyrande', 'quest_complete', 'It is done. Elune smiles on the deed.', '', '', '', -1, -1, '', '', '', 0, 1),
('tyrande', 'quest_complete', 'Well done. You have a good heart. Guard it.', '', '', '', -1, -1, '', '', '', 0, 1),
('tyrande', 'quest_complete', 'There. The world turns a little easier now.', '', '', '', -1, -1, '', '', '', 0, 1),
('tyrande', 'quest_complete', 'Good. Let us rest a moment, and then go on.', '', '', '', -1, -1, '', '', '', 0, 1),
('tyrande', 'combat_start', 'Elune, be my light.', '', '', '', 0, -1, '', '', '', 0, 1),
('tyrande', 'combat_start', 'Stand fast.', '', '', '', 0, -1, '', '', '', 0, 1),
('tyrande', 'combat_start', 'I am with you.', '', '', '', 0, -1, '', '', '', 0, 1),
('tyrande', 'combat_start', 'Strike true. I will mend.', '', '', '', 0, -1, '', '', '', 0, 1),
('tyrande', 'combat_start', '%target. Hold steady, all of you. I will keep you standing.', '', '', '', 1, -1, '', '', '', 0, 1),
('tyrande', 'combat_start', 'This one is strong. Trust me, and trust each other.', '', '', '', 1, -1, '', '', '', 0, 1),
('tyrande', 'combat_start', 'Elune, guard them!', '', '', '', 1, -1, '', '', '', 0, 1),
('tyrande', 'combat_start', 'The Legion. Ten thousand years, and you still crawl back. We will send you back again.', '', '3', '', -1, -1, '', '', '', 0, 1),
('tyrande', 'combat_start', 'Demons. I have fought your kind since before this world had a name for you.', '', '3', '', -1, -1, '', '', '', 0, 1),
('tyrande', 'combat_start', 'Unliving things. Elune''s light will show you your way.', '', '6', '', -1, -1, '', '', '', 0, 1),
('tyrande', 'combat_start', 'Hyjal, again. Very well. I held this mountain once. I will hold it twice.', '', '', 'archimonde|anetheron|azgalor|kaz''rogal|rage winterchill', -1, -1, '', '', '', 0, 1),
('tyrande', 'combat_start', 'Illidan. ...I wish I had never set you free. I wish you had been worth it.', '', '', 'illidan stormrage', -1, -1, '', '', '', 0, 1),
('tyrande', 'combat_start', 'The Old Gods. They whispered in Azshara''s ear before the Sundering. Do not listen to it. Listen to me.', '', '', 'c''thun', -1, -1, '', '', '', 0, 1),
('tyrande', 'combat_start', 'Lich King. You have made a desert of the dead. Elune''s light will reach even you.', '', '', 'the lich king', -1, -1, '', '', '', 0, 1),
('tyrande', 'kill', 'Rest.', '', '', '', 0, -1, '', '', '', 0, 1),
('tyrande', 'kill', 'It is done.', '', '', '', 0, -1, '', '', '', 0, 1),
('tyrande', 'kill', 'Elune guide you.', '', '', '', 0, -1, '', '', '', 0, 1),
('tyrande', 'kill', '%target is fallen. Well fought, all of you.', '', '', '', 1, -1, '', '', '', 0, 1),
('tyrande', 'kill', 'It is over. Breathe.', '', '', '', 1, -1, '', '', '', 0, 1),
('tyrande', 'kill', 'Elune be thanked.', '', '', '', 1, -1, '', '', '', 0, 1),
('tyrande', 'kill', 'Back into the dark with you. And stay there.', '', '3', '', -1, -1, '', '', '', 0, 1),
('tyrande', 'kill', 'Archimonde, again. You died beneath the World Tree once. I see you have not learned.', '', '', 'archimonde', -1, -1, '', '', '', 0, 1),
('tyrande', 'kill', 'Goodbye, Illidan. I hope, wherever you are, you are finally at peace.', '', '', 'illidan stormrage', -1, -1, '', '', '', 0, 1),
('tyrande', 'kill', 'The Lich King has fallen. Elune be praised. The north will see a sunrise.', '', '', 'the lich king', -1, -1, '', '', '', 0, 1),
('tyrande', 'death', 'Elune... forgive...', '', '', '', -1, -1, '', '', '', 0, 1),
('tyrande', 'death', 'Malfurion...', '', '', '', -1, -1, '', '', '', 0, 1),
('tyrande', 'death', 'The light... dims...', '', '', '', -1, -1, '', '', '', 0, 1),
('tyrande', 'revived', 'Elune has not finished with me.', '', '', '', -1, -1, '', '', '', 0, 1),
('tyrande', 'revived', 'Thank you. My goddess thanks you too.', '', '', '', -1, -1, '', '', '', 0, 1),
('tyrande', 'revived', 'I am well. Let us go on.', '', '', '', -1, -1, '', '', '', 0, 1),
('tyrande', 'ally_down', '%other! Elune, give me strength!', '', '', '', -1, -1, '', '', '', 0, 1),
('tyrande', 'ally_down', '%other is down! Stay with me!', '', '', '', -1, -1, '', '', '', 0, 1),
('tyrande', 'ally_down', 'No. %other, stay with me!', '', '', '', -1, -1, '', '', '', 0, 1),
('tyrande', 'grow_stronger', 'Elune''s light comes to me more easily now. As if she is leaning closer.', '', '', '', -1, -1, '', '', '', 0, 1),
('tyrande', 'grow_stronger', 'I feel stronger. The wounds close faster under my hands.', '', '', '', -1, -1, '', '', '', 0, 1),
('tyrande', 'grow_stronger', 'My prayers carry further now. Good.', '', '', '', -1, -1, '', '', '', 0, 1),
('tyrande', 'grow_stronger', 'Something is waking in me. Old strength, remembered.', '', '', '', -1, -1, '', '', '', 0, 1);
